CREATE TABLE IF NOT EXISTS gis_geometry_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version text NOT NULL, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, source_geometry jsonb, target_geometry jsonb, overlap_score numeric(8,5) NOT NULL DEFAULT 0, centroid_distance_score numeric(8,5) NOT NULL DEFAULT 0, containment_score numeric(8,5) NOT NULL DEFAULT 0, geometry_method text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id,target_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_geometry_evidence_version ON gis_geometry_evidence(crosswalk_version,source_feature_id);